// Compare the review alerts that just arrived with what is already in the ledger,
// and only pass on the NEW ones. Each new alert keeps its own email data, so
// several reviews arriving in the same minute are each handled on their own.
// (Runs once for all items.)
const logged = new Set(
  $input.all().map(i => String(i.json.gmail_message_id ?? '').trim()).filter(Boolean)
);

// Google's notification emails are often HTML-only: turn the HTML into plain text
// so the AI reads the review, not the markup.
const stripHtml = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>|<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"')
  .replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();

const out = [];
for (const it of $('Watch Gmail for new review alerts').all()) {
  const id = String(it.json.id ?? '');
  if (!id || logged.has(id)) continue;

  const text =
    (it.json.text && String(it.json.text).trim()) ||
    stripHtml(it.json.html) ||
    String(it.json.subject ?? '');

  out.push({
    json: {
      id,
      subject: it.json.subject ?? '',
      date: it.json.date ?? '',
      text: text.slice(0, 6000),
    },
  });
}
return out;

// Runs once for EACH item, so several reviews arriving together are each checked.
// Check the AI's draft before it reaches a human. Three jobs:
//   1. Make sure the AI actually read a review instead of inventing one. Google keeps
//      changing these notification emails, and an LLM handed an empty alert will
//      cheerfully make up a rating and a complaint. That is the worst possible failure
//      here, so the excerpt it claims to have found must really appear in the email.
//   2. Decide whether this alert was readable at all. A silent skip is worse than a warning.
//   3. Check the draft against the rules Google applies to public replies, so a reply
//      that would be rejected never gets pasted in the first place.
const settings = $('⚙️ Your settings').first().json;
const alertText = String($('Keep only the new review alerts').item.json.text || '');
const out       = $json.output || {};
const rating    = Number(out.rating);
const draft     = String(out.reply_draft || '').trim();

const flatten = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const source  = flatten(alertText);
const excerpt = flatten(out.review_excerpt);
const probe   = excerpt.slice(0, 40);
// If the words the AI quoted are not in the email, it did not read a review — it wrote one.
const grounded = probe.length >= 12 && source.includes(probe);

const usable = grounded && Number.isFinite(rating) && rating >= 1 && rating <= 5 && draft.length > 0;

// Digits only, so "(312) 555-0143" and "312-555-0143" compare equal.
const digits = (s) => String(s || '').replace(/\D/g, '');
const ownContact = digits(settings.contactChannel);

const flags = [];
if (/https?:\/\/|www\./i.test(draft)) flags.push('contains a link');

// Your own phone number is allowed — Google only objects to other people's details.
// Flag a number ONLY when it is not the contact channel you configured.
for (const m of draft.match(/\+?\d[\d ().-]{7,}\d/g) || []) {
  const dg = digits(m);
  if (dg && ownContact && (ownContact.includes(dg) || dg.includes(ownContact))) continue;
  flags.push('contains a phone number that is not your contact channel (' + m.trim() + ')');
  break;
}

if (/\b(discount|coupon|voucher|% ?off|free (meal|drink|item|night|session)|refund)\b/i.test(draft))
  flags.push('offers a discount or refund');
if (/\b(change|update|revise|remove|delete|take down)\b[^.]{0,40}\b(review|rating|star)/i.test(draft))
  flags.push('asks the reviewer to change the rating');

const words = draft ? draft.split(/\s+/).length : 0;
if (words > 130) flags.push('runs to ' + words + ' words');

const status = !grounded    ? 'could-not-read: the draft was not grounded in the email'
             : !usable      ? 'could-not-read'
             : flags.length ? 'flagged: ' + flags.join('; ')
             : rating <= 2  ? 'low-rating-escalated'
                            : 'draft-sent-to-owner';

return { json: { ...$json, usable, grounded, flags, lowRating: usable && rating <= 2, wordCount: words, status } };
